// Function to calculate the lead score for a single lead object
function calculateLeadScore(lead) {
  let score = 0;
  let hs_lead_status = lead.properties.hs_lead_status;
  let hs_lifecycle_stage = lead.properties.lifecyclestage;
  const research_tags = [];

  const props = (lead && lead.properties) ? lead.properties : {};

  // 1. E-Commerce Platform
  const knownPlatforms = ['shopify', 'big commerce', 'bigcommerce', 'magento', 'volusion', 'woo commerce', 'woocommerce', 'wix'];
  const platform = (props.ecommerce_platform || '').toString().toLowerCase();

  if (knownPlatforms.includes(platform)) {
    score += 7;
  } else if (platform === 'other') {
    score += 3;
  } else if (platform === 'unknown' || !platform) {
    score -= 20;
  }

  // 2. Physical Address Listed
  const addressListed = props.address_listed_on_website_;
  if (addressListed === 'yes') {
    score += 10;
  } else if (addressListed === 'no') {
    score -= 15;
  }

  // 3. Business Model (B2B / B2C)
  const sellsB2B = props.do_the_sell_b2b;
  if (sellsB2B === 'yes') {
    score += 5;
  } else {
    hs_lead_status = "Unqualified Revenue Less 1 mil"
    hs_lifecycle_stage = "1410598780"
  }
  const sellsB2C = props.do_the_sell_b2c;
  if (sellsB2C === 'yes') {
    score += 10;
  } else if (sellsB2C === 'no') {
    score -= 15;
    hs_lead_status = "Unqualified Revenue Less 1 mil"
    hs_lifecycle_stage = "1410598780"
  }

  // 4. Year Founded
  const founded = parseInt(props.founded_year, 10);
  if (!isNaN(founded)) {
    if (founded >= 2020) {
      score += 3;
    } else if (founded >= 2000 && founded <= 2019) {
      score += 2;
    } else if (founded > 0 && founded < 2000) {
      score += 1;
    }
  }

  // 5. Revenue Range (HubSpot)
  const hs_revenue_range = parseFloat(props.hs_revenue_range) || 0;

  if (hs_revenue_range > 0 && hs_revenue_range <= 1000000) {
    score += 3;
  } else if (hs_revenue_range > 1000000 && hs_revenue_range <= 10000000) {
    score += 25;
  } else if (hs_revenue_range > 10000000 && hs_revenue_range <= 50000000) {
    score += 10;
  } else if (hs_revenue_range > 50000000 && hs_revenue_range <= 100000000) {
    score -= 30;
    hs_lead_status = "Unqualified Revenue Plus 100 mil"
    hs_lifecycle_stage = "1410598780"
  } else if (hs_revenue_range > 100000000 && hs_revenue_range <= 200000000) {
    score -= 40;
    hs_lead_status = "Unqualified Revenue Plus 100 mil"
    hs_lifecycle_stage = "1410598780"
  } else if (hs_revenue_range > 250000000 && hs_revenue_range <= 500000000) {
    score -= 50;
    hs_lead_status = "Unqualified Revenue Plus 100 mil"
    hs_lifecycle_stage = "1410598780"
  } else if (hs_revenue_range > 500000000 && hs_revenue_range <= 1000000000) {
    score -= 60;
    hs_lead_status = "Unqualified Revenue Plus 100 mil"
    hs_lifecycle_stage = "1410598780"
  } 

  const hs_annual_revenue = parseFloat(props.annualrevenue) || 0;
  if (hs_annual_revenue > 500000 && hs_annual_revenue <= 1500000) {
    score += 5;
  } else if (hs_annual_revenue > 1500000 && hs_annual_revenue <= 10000000) {
    score += 10;
  } else if (hs_annual_revenue > 10000000 && hs_annual_revenue <= 30000000) {
    score += 7;
  } else if (hs_annual_revenue > 30000000) {
    score -= 50;
    hs_lead_status = "Unqualified Revenue Plus 100 mil"
    hs_lifecycle_stage = "1410598780"
  }

  // 5. Annual Revenue (Scraper)
  const revenue = parseFloat(props.total_revenue) || 0;
  if (revenue > 30000000) {
    score -= 50;
    hs_lead_status = "Unqualified Revenue Plus 100 mil"
    hs_lifecycle_stage = "1410598780"
  } else if (revenue > 20000000 && revenue <= 30000000) {
    score += 5;
  } else if (revenue > 5000000 && revenue <= 20000000) {
    score += 15;
  } else if (revenue == 5000000) {
    score += 10;
  }
  // 6. Shipping Carriers & Methods
  const carriers = (props.scraper_carriers || '').toString().toUpperCase();
  if (carriers.includes('UPS') || carriers.includes('FEDEX')) {
    score += 10;
  }

  const shippingMsg = (props.scraper_shipping_messages || '').toString().toLowerCase();
  if (shippingMsg.includes('free')) {
    research_tags.push("Free Shipping Offered");
  }

  const shipMethod = (props.scraper_shipping_methods || '').toString().toLowerCase();
  if (shipMethod === 'international') {
    score += 10;
    research_tags.push("International Shipping Needs");
  } else if (shipMethod === 'domestic only') {
    score += 5;
  }

  // 7. Product Cubic Size & Pricing
  const smallestCubic = parseFloat(props.scraper_smallest_product_cubic) || 0;
  if (smallestCubic >= 30000) {
    score += 5;
    research_tags.push("LTL / Freight Suspect");
  } else if (smallestCubic > 15000 && smallestCubic <= 30000) {
    score += 15;
  } else if (smallestCubic > 3000 && smallestCubic <= 15000) {
    score += 10;
  } else if (smallestCubic > 0 && smallestCubic <= 3000) {
    score -= 5;
  }
  const smallestPrice = parseFloat(props.scraper_smallest_product_cubic) || 0;
  if (smallestPrice < 10) {
  } else if (smallestPrice > 100 && smallestPrice <= 1000) {
    score += 5;
  }

  // 7. Product Cubic Size & Pricing
  const largestCubic = parseFloat(props.scraper_largest_product_cubic) || 0;
  if (largestCubic < 1000) {
  } else if (largestCubic >= 1000 && largestCubic < 3000) {
    score += 2;
  } else if (largestCubic >= 3000 && largestCubic < 15000) {
    score += 10;
    research_tags.push("Ideal Size Products");
  } else if (largestCubic >= 15000 && largestCubic < 30000) {
    score += 15;
  } else if (largestCubic > 30000) {
    score += 5;
    research_tags.push("LTL / Freight Suspect");
  }
  const largestPrice = parseFloat(props.scraper_largest_product_cubic) || 0;
  if (largestPrice > 0 && largestPrice <= 20) {
    score -= 10;
    research_tags.push("Low Value Products");
  } else if (largestPrice > 20 && largestPrice <= 100) {
    score += 5;
    research_tags.push("Low Value Products");
  } else if (largestPrice > 100 && largestPrice <= 1000) {
    score += 10;
    research_tags.push("Ideal Value Products");
  } else if (largestPrice > 1000 && largestPrice <= 5000) {
    score += 5;
    research_tags.push("High Value Products");
  } else if (largestPrice > 5000) {
    research_tags.push("High Value Products");
  }

  // 8. Verified Industry Type
  const industry = (props.industry_type_verified || '').toString().toLowerCase();
  const topTierIndustries = ['auto parts', 'sporting goods', 'outdoor', 'electronics'];
  const midTierIndustries = ['home goods', 'industrial or manufacturing', 'food and beverage'];
  const lowTierIndustries = ['apparel', 'cosmetics', 'medical', '3pl'];

  if (topTierIndustries.some(i => industry.includes(i))) {
    score += 10;
  } else if (midTierIndustries.some(i => industry.includes(i))) {
    score += 5;
  } else if (lowTierIndustries.some(i => industry.includes(i))) {
    score += 2;
  }

  // 9. Contact Info (Phone)
  const phone = (props.confirmed_website___headquarters_phone__ || '').toString().trim();
  if (!phone || phone.toLowerCase() === null || phone.toLowerCase() === '') {
    score -= 30;
  } else {
    score += 10;
  }

  // 10. Monthly Web Visits & Sales Routing Logic
  const visits = parseFloat(props.total_monthly_visits) || 0;
  if (visits > 500000) {
    score -= 75;
    hs_lead_status = "Unqualified Revenue Plus 100 mil"
    hs_lifecycle_stage = "1410598780"
    research_tags.push("Extra Large Web Traffic");
  } else if (visits > 150000 && visits <= 500000) {
    score += 45;
    research_tags.push("Big Web Traffic");
  } else if (visits > 90000 && visits <= 150000) {
    score += 40;
    research_tags.push("Big Web Traffic");
  } else if (visits > 60000 && visits <= 90000) {
    score += 35;
    research_tags.push("Big Web Traffic");
  } else if (visits > 30000 && visits <= 60000) {
    score += 30;
    research_tags.push("Ideal Web Traffic");
  } else if (visits > 10000 && visits <= 30000) {
    score += 25;
    research_tags.push("Ideal Web Traffic");
  } else if (visits > 5000 && visits <= 10000) {
    score += 20;
    research_tags.push("Ideal Web Traffic");
  } else if (visits > 3000 && visits <= 5000) {
    score += 15;
    research_tags.push("Ideal Web Traffic");
  } else if (visits > 1000 && visits <=3000) {
    score -= 10;
    research_tags.push("Small Web Traffic");
  } else if (visits > 100 && visits <= 1000) {
    score -= 25;
    research_tags.push("Small Web Traffic");
  } else if (visits > 0 && visits <= 100) {
    score -= 50;
    hs_lead_status = "Unqualified Revenue Less 1 mil"
    hs_lifecycle_stage = "1410598780"
  }

  // 11. US Traffic Ratio
  let usTrafficRatio = parseFloat(props.usa_traffic);
  if (isNaN(usTrafficRatio)) {
    usTrafficRatio = 1.0;
  }

  if (usTrafficRatio < 0.5) {
    score -= 10;
    hs_lead_status = "Unqualified Revenue Less 1 mil"
    hs_lifecycle_stage = "1410598780"
    // tags.push('suspected non-us based');
  } else if (usTrafficRatio > 0.5 && usTrafficRatio <= 0.9) {
    score += 5;
    research_tags.push("International Shipping Needs");
    // tags.push('International shipping suspect');
  }
  const is_website_live = props.is_website_live_;
  if (industry == "na" && (is_website_live == "" || is_website_live == null)) {
    score = -4444444
  }
  const currentDate = new Date().toISOString().split('T')[0];

  return {
    id: lead.id,
    properties: {
      lead_score: score,
      lead_score_date: currentDate,
      lead_score_request_status: "completed",
      research_tags: research_tags.join(";")
    }
  };
}

// ==========================================
// N8N ARRAY PARSING LOGIC:
// ==========================================

const outputItems = [];

// Loop through each incoming n8n item and calculate scores
for (const item of $input.all()) {
  const results = item.json.results || [];
  for (const record of results) {
    outputItems.push(calculateLeadScore(record));
  }
}

// Split the parsed output items into chunks of 100
const chunkSize = 100;
const finalBatches = [];

for (let i = 0; i < outputItems.length; i += chunkSize) {
  const chunk = outputItems.slice(i, i + chunkSize);
  finalBatches.push({
    json: {
      results: chunk
    }
  });
}
return finalBatches;
